create or replace function game.on_map(x integer, y integer)
 returns boolean
 language sql
 stable
 set search_path to 'pg_catalog', 'game'
as $$
  select (x between 0 and 159 and y between 0 and 108)
    or (x between 18 and 41 and y between 115 and 126)
    or (x between 42 and 45 and y between 116 and 116)
    or (x between 46 and 55 and y between 114 and 121)
    or exists (select 1 from game.beach b where b.y = $2 and $1 between b.x0 and b.x1)
$$;
revoke execute on function game.on_map(integer, integer) from public, anon, authenticated;

insert into public.stations (id, kind, x, y) values ('barrel_1', 'bbq', 63, 48)
on conflict (id) do update set kind = excluded.kind, x = excluded.x, y = excluded.y;
insert into public.spots (id, crime_id, x, y, area_x0, area_y0, area_x1, area_y1) values
  ('meter_5', 'parking_meter', 111, 79, null, null, null, null),
  ('car_4', 'steal_car', 111, 78, null, null, null, null)
on conflict (id) do update set x = excluded.x, y = excluded.y;
update game.walk_map set masks = '' where y = 75;
update game.walk_map set masks = '' where y = 76;
update game.walk_map set masks = '' where y = 77;
update game.walk_map set masks = '' where y = 78;
update game.walk_map set masks = '' where y = 79;

select
  case when (select count(*) from game.beach) = 258 and game.on_map(19, -4) and not game.on_map(-6, -6)
    and game.on_map(0, 0) then 'ok' else 'BAD BEACH' end as beach,
  case when exists (select 1 from public.stations where id = 'barrel_1')
    and (select y from public.spots where id = 'meter_5') = 79 then 'ok' else 'BAD ROWS' end as rows;

commit;
